param([Parameter(Mandatory=$true)][string]$SavePath)
# Offline XML extraction; preserves omission separately from numeric or boolean values.
$ErrorActionPreference='Stop'
$s=[xml](Get-Content -Raw -LiteralPath $SavePath)
function Number($n,[string]$field){$v=$n.SelectSingleNode($field);[ordered]@{present=($null -ne $v);value=if($v){[double]::Parse($v.InnerText,[Globalization.CultureInfo]::InvariantCulture)}else{$null}}}
function Flag($n,[string]$field){$v=$n.SelectSingleNode($field);[ordered]@{present=($null -ne $v);value=if($v){$v.InnerText -eq 'True'}else{$null}}}
function Raw($n,[string]$field){$v=$n.SelectSingleNode($field);if($v){$v.OuterXml}else{$null}}
function Item($n){[ordered]@{id=[string]$n.id;def=[string]$n.def;pos=[string]$n.pos;stack_count=(Number $n 'stackCount');hp=(Number $n 'health');forbidden=(Flag $n 'forbidden');owner=[string]$n.SelectSingleNode('ancestor::*[def="Human"][1]/id').InnerText;container=$n.ParentNode.ParentNode.Name;raw=$n.OuterXml}}
function Condition($n){[ordered]@{id=[int]$n.loadID;class=[string]$n.Class;def=[string]$n.def;body=[string]$n.part.body;part_index=(Number $n 'part/index');severity=(Number $n 'severity');tick_added=(Number $n 'tickAdded');age_ticks=(Number $n 'ageTicks');permanent=(Flag $n 'isPermanent');tend_ticks_left=(Number $n 'tendTicksLeft');tend_quality=(Number $n 'tendQuality');total_tend_quality=(Number $n 'totalTendQuality');ticks_until_infect=(Number $n 'ticksUntilInfect');infection_chance_factor=(Number $n 'infectionChanceFactor');raw=$n.OuterXml}}
$map=$s.SelectSingleNode('//thing[id="Human958"]').ParentNode.ParentNode
$pawns=@($map.SelectNodes('./things/thing[def="Human"]')|ForEach-Object{
 $p=$_
 [ordered]@{id=[string]$p.id;nick=[string]$p.name.nick;pos=[string]$p.pos;health_state=[string]$p.healthTracker.healthState;medical_care=[string]$p.playerSettings.medCare;player_settings=(Raw $p 'playerSettings');drafter=(Raw $p 'drafter');work_priorities=(Raw $p 'workSettings/priorities');hediffs=@($p.SelectNodes('healthTracker/hediffSet/hediffs/li')|ForEach-Object{Condition $_});immunity=(Raw $p 'healthTracker/immunity');health_tracker=(Raw $p 'healthTracker');job=(Raw $p 'jobs/curJob');job_driver=(Raw $p 'jobs/curDriver');stance=(Raw $p 'stances/curStance');pather=(Raw $p 'pather');mental_state=(Raw $p 'mindState/mentalStateHandler');carry=(Raw $p 'carryTracker');inventory=(Raw $p 'inventory');equipment=(Raw $p 'equipment');skills=@($p.SelectNodes('skills/skills/li')|ForEach-Object{[ordered]@{def=[string]$_.def;level=(Number $_ 'level');xp_since_level=(Number $_ 'xpSinceLastLevel');xp_since_midnight=(Number $_ 'xpSinceMidnight');passion=[string]$_.passion;raw=$_.OuterXml}});needs=@($p.SelectNodes('needs/needs/li')|ForEach-Object{[ordered]@{def=[string]$_.def;level=(Number $_ 'curLevel')}});traits=(Raw $p 'story/traits');apparel=(Raw $p 'apparel')}
}|Sort-Object {$_.id})
[ordered]@{file=(Split-Path -Leaf $SavePath);sha256=(Get-FileHash -LiteralPath $SavePath -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item -LiteralPath $SavePath).Length;version=$s.SelectSingleNode('//meta/gameVersion').InnerText;mods=@($s.SelectNodes('//meta/modIds/li')|ForEach-Object{$_.InnerText});tick=[int]$s.SelectSingleNode('//tickManager/ticksGame').InnerText;tick_manager_raw=$s.SelectSingleNode('//tickManager').OuterXml;pawns=$pawns;medicines=@($map.SelectNodes('.//*[id and starts-with(def,"Medicine")]')|ForEach-Object{Item $_}|Sort-Object {$_.id});beds=@($map.SelectNodes('./things/thing[@Class="Building_Bed"]')|ForEach-Object{[ordered]@{id=[string]$_.id;def=[string]$_.def;pos=[string]$_.pos;stuff=[string]$_.stuff;quality=[string]$_.quality;medical=(Flag $_ 'medical');raw=$_.OuterXml}}|Sort-Object {$_.id});scope='Read-only original XML for current-map humans, medicine including carried/inventory containers, beds and tick manager. Numeric/bool fields retain explicit presence and null absence. Complete health tracker XML retains immunity records and disease component fields. No computed stats, inferred defaults, OCR or simulated treatment are inserted.'}|ConvertTo-Json -Depth 35
